44: void CryptoParametersRNS::PrecomputeCRTTables(KeySwitchTechnique ksTech, ScalingTechnique scalTech,
45:                                               EncryptionTechnique encTech, MultiplicationTechnique multTech,
46:                                               uint32_t numPartQ, uint32_t auxBits, uint32_t extraBits) {
47:     // Set the key switching technique.
48:     m_ksTechnique = ksTech;
49:     // Set the scaling technique.
50:     m_scalTechnique = scalTech;
51:     // Set the key encryption technique.
52:     m_encTechnique = encTech;
53:     // Set the multiplication technique.
54:     m_multTechnique = multTech;
55:     // Set number of digits in HYBRID
56:     m_numPartQ = numPartQ;
57:     // Set auxiliary primes bit size in HYBRID
58:     m_auxBits = auxBits;
59:     // Set number of extraBits for lower error
60:     m_extraBits = extraBits;
61: 
62:     size_t sizeQ = GetElementParams()->GetParams().size();
63:     size_t n     = GetElementParams()->GetRingDimension();
64: 
65:     // Construct moduliQ and rootsQ from crypto parameters
66:     std::vector<NativeInteger> moduliQ(sizeQ);
67:     std::vector<NativeInteger> rootsQ(sizeQ);
68:     for (size_t i = 0; i < sizeQ; i++) {
69:         moduliQ[i] = GetElementParams()->GetParams()[i]->GetModulus();
70:         rootsQ[i]  = GetElementParams()->GetParams()[i]->GetRootOfUnity();
71:     }
72: 
73:     // Pre-compute CRT::FFT values for Q
74:     DiscreteFourierTransform::Initialize(n * 2, n / 2);
75:     ChineseRemainderTransformFTT<NativeVector>().PreCompute(rootsQ, 2 * n, moduliQ);
76:     if (m_ksTechnique == HYBRID) {
77:         // numPartQ can not be zero as there is a division by numPartQ
78:         if (numPartQ == 0)
79:             OPENFHE_THROW("numPartQ is zero");
80: 
81:         // Compute ceil(sizeQ/numPartQ), the # of towers per digit
82:         uint32_t a = static_cast<uint32_t>(std::ceil(static_cast<double>(sizeQ) / numPartQ));
83:         if (sizeQ <= (a * (numPartQ - 1))) {
84:             auto str = "HYBRID key switching parameters: Can't appropriately distribute " + std::to_string(sizeQ) +
85:                        " towers into " + std::to_string(numPartQ) +
86:                        " digits. Please select different number of digits.";
87:             OPENFHE_THROW(str);
88:         }
89: 
90:         m_numPerPartQ = a;

127:         // Find number and size of individual special primes.
128:         uint32_t maxBits = moduliPartQ[0].GetLengthForBase(2);
129:         for (uint32_t j = 1; j < m_numPartQ; j++) {
130:             uint32_t bits = moduliPartQ[j].GetLengthForBase(2);
131:             if (bits > maxBits)
132:                 maxBits = bits;
133:         }
134:         // Select number of primes in auxiliary CRT basis
135:         uint32_t sizeP = static_cast<uint32_t>(std::ceil(static_cast<double>(maxBits) / auxBits));
136: 
137:         uint64_t primeStep = FindAuxPrimeStep();
138: 
139:         // Choose special primes in auxiliary basis and compute their roots
140:         // moduliP holds special primes p1, p2, ..., pk
141:         // m_modulusP holds the product of special primes P = p1*p2*...pk
142:         std::vector<NativeInteger> moduliP(sizeP);
143:         std::vector<NativeInteger> rootsP(sizeP);
144:         // firstP contains a prime whose size is PModSize.
145:         NativeInteger firstP = FirstPrime<NativeInteger>(auxBits, primeStep);
146:         NativeInteger pPrev  = firstP;
147:         BigInteger modulusP(1);
148:         for (uint32_t i = 0; i < sizeP; i++) {
149:             // The following loop makes sure that moduli in
150:             // P and Q are different
151:             bool foundInQ = false;
152:             do {
153:                 moduliP[i] = PreviousPrime<NativeInteger>(pPrev, primeStep);
154:                 foundInQ   = false;
155:                 for (usint j = 0; j < sizeQ; j++)
156:                     if (moduliP[i] == moduliQ[j])
157:                         foundInQ = true;
158:                 pPrev = moduliP[i];
159:             } while (foundInQ);
160:             rootsP[i] = RootOfUnity<NativeInteger>(2 * n, moduliP[i]);
161:             modulusP *= moduliP[i];
162:             pPrev = moduliP[i];
163:         }
164: 
165:         // Store the created moduli and roots in m_paramsP
166:         m_paramsP = std::make_shared<ILDCRTParams<BigInteger>>(2 * n, moduliP, rootsP);
167: 
168:         // Create the moduli and roots for the extended CRT basis QP
169:         std::vector<NativeInteger> moduliQP(sizeQ + sizeP);
170:         std::vector<NativeInteger> rootsQP(sizeQ + sizeP);
171:         for (size_t i = 0; i < sizeQ; i++) {
172:             moduliQP[i] = moduliQ[i];
173:             rootsQP[i]  = rootsQ[i];
174:         }
175:         for (size_t i = 0; i < sizeP; i++) {
176:             moduliQP[sizeQ + i] = moduliP[i];
177:             rootsQP[sizeQ + i]  = rootsP[i];
178:         }
179: 
180:         m_paramsQP = std::make_shared<ILDCRTParams<BigInteger>>(2 * n, moduliQP, rootsQP);
181: 
182:         // Pre-compute CRT::FFT values for P
183:         ChineseRemainderTransformFTT<NativeVector>().PreCompute(rootsP, 2 * n, moduliP);

