46: template <class Element>
47: KeyPair<Element> PKEBase<Element>::KeyGenInternal(CryptoContext<Element> cc, bool makeSparse) const {
48:     const auto cryptoParams  = std::dynamic_pointer_cast<CryptoParametersRLWE<Element>>(cc->GetCryptoParameters());
49:     const auto elementParams = cryptoParams->GetElementParams();
50:     const auto paramsPK      = cryptoParams->GetParamsPK();
51:     if (!paramsPK)
52:         OPENFHE_THROW("PrecomputeCRTTables() must be called before using precomputed params.");
53: 
54:     // Private Key Generation
55: 
56:     const DggType& dgg = cryptoParams->GetDiscreteGaussianGenerator();
57:     TugType tug;
58: 
59:     Element s;
60:     switch (cryptoParams->GetSecretKeyDist()) {
61:         case GAUSSIAN:
62:             s = Element(dgg, paramsPK, Format::EVALUATION);
63:             break;
64:         case UNIFORM_TERNARY:
65:             s = Element(tug, paramsPK, Format::EVALUATION);
66:             break;
67:         case SPARSE_TERNARY:
68:         case SPARSE_ENCAPSULATED:
69:             // https://github.com/openfheorg/openfhe-development/issues/311
70:             s = Element(tug, paramsPK, Format::EVALUATION, 192);
71:             break;
72:         default:
73:             OPENFHE_THROW("Unknown SecretKeyDist.");
74:     }
75: 
76:     // Public Key Generation
77: 
78:     DugType dug;
79:     Element a(dug, paramsPK, Format::EVALUATION);
80: 
81:     Element e(dgg, paramsPK, Format::EVALUATION);
82:     NativeInteger ns = cryptoParams->GetNoiseScale();
83: 
84:     // b = ns * e - a * s
85:     Element b(std::move((e *= ns) -= (a * s)));
86: 
87:     auto sizeQ  = elementParams->GetParams().size();
88:     auto sizePK = paramsPK->GetParams().size();
89:     if (sizePK > sizeQ)
90:         s.DropLastElements(sizePK - sizeQ);
91: 
92:     KeyPair<Element> keyPair(std::make_shared<PublicKeyImpl<Element>>(cc),
93:                              std::make_shared<PrivateKeyImpl<Element>>(cc));
94:     keyPair.secretKey->SetPrivateElement(std::move(s));
95:     keyPair.publicKey->SetPublicElements({std::move(b), std::move(a)});
96:     keyPair.publicKey->SetKeyTag(keyPair.secretKey->GetKeyTag());
97:     return keyPair;
98: }

