112:         h = size;
113: 
114:     std::vector<int32_t> v(size);
115: 
116:     auto distrHWT = std::uniform_int_distribution<int32_t>(0, size - 1);
117:     BinaryUniformGeneratorImpl<VecType> bug;
118:     uint32_t counterPlus = 0;
119: 
120:     // makes sure the +1's and -1's are roughly evenly distributed
121:     while ((counterPlus < h / 2 - 1) || (counterPlus > h / 2 + 1)) {
122:         // initializes all values
123:         counterPlus = 0;
124:         for (uint32_t k = 0; k < size; ++k)
125:             v[k] = 0;
126: 
127:         uint32_t i = 0;
128:         while (i < h) {
129:             // random index in the vector
130:             auto randomIndex = distrHWT(PseudoRandomNumberGenerator::GetPRNG());
131:             if (v[randomIndex] == 0) {
132:                 if (bug.GenerateInteger() == typename VecType::Integer(0)) {
133:                     v[randomIndex] = -1;
134:                 }
135:                 else {
136:                     v[randomIndex] = 1;
137:                     ++counterPlus;
138:                 }
139:                 ++i;
140:             }
141:         }
142:     }
143:     return v;

50: // makeSparse is not used by this scheme
51: template <class Element>
52: KeyPair<Element> MultipartyBase<Element>::MultipartyKeyGen(CryptoContext<Element> cc,
53:                                                            const std::vector<PrivateKey<Element>>& privateKeyVec,
54:                                                            bool makeSparse) {
55:     const auto cryptoParams  = std::dynamic_pointer_cast<CryptoParametersRLWE<Element>>(cc->GetCryptoParameters());
56:     const auto elementParams = cryptoParams->GetElementParams();
57: 
58:     // Private Key Generation
59: 
60:     Element s(elementParams, Format::EVALUATION, true);
61:     for (auto& pk : privateKeyVec)
62:         s += pk->GetPrivateElement();
63: 
64:     // Public Key Generation
65: 
66:     DugType dug;
67:     Element a(dug, elementParams, Format::EVALUATION);
68: 
69:     Element e(cryptoParams->GetDiscreteGaussianGenerator(), elementParams, Format::EVALUATION);
70:     NativeInteger ns = cryptoParams->GetNoiseScale();
71: 
72:     // b = ns * e - a * s
73:     Element b(std::move((e *= ns) -= (a * s)));
74: 
75:     KeyPair<Element> keyPair(std::make_shared<PublicKeyImpl<Element>>(cc),
76:                              std::make_shared<PrivateKeyImpl<Element>>(cc));
77:     keyPair.secretKey->SetPrivateElement(std::move(s));
78:     keyPair.publicKey->SetPublicElements({std::move(b), std::move(a)});
79:     return keyPair;
80: }

111: std::shared_ptr<std::vector<DCRTPoly>> PKERNS::EncryptZeroCore(const PrivateKey<DCRTPoly> privateKey,
112:                                                                const std::shared_ptr<ParmType> params) const {
113:     const auto cryptoParams = std::dynamic_pointer_cast<CryptoParametersRNS>(privateKey->GetCryptoParameters());
114: 
115:     const DCRTPoly& s  = privateKey->GetPrivateElement();
116:     const auto ns      = cryptoParams->GetNoiseScale();
117:     const DggType& dgg = cryptoParams->GetDiscreteGaussianGenerator();
118:     DugType dug;
119: 
120:     const std::shared_ptr<ParmType> elementParams = (params == nullptr) ? cryptoParams->GetElementParams() : params;
121: 
122:     DCRTPoly a(dug, elementParams, Format::EVALUATION);
123:     DCRTPoly e(dgg, elementParams, Format::EVALUATION);
124: 
125:     uint32_t sizeQ  = s.GetParams()->GetParams().size();
126:     uint32_t sizeQl = elementParams->GetParams().size();
127: 
128:     DCRTPoly c0, c1;
129:     if (sizeQl != sizeQ) {
130:         // Clone secret key because we need to drop towers.
131:         DCRTPoly scopy(s);
132: 
133:         uint32_t diffQl = sizeQ - sizeQl;
134:         scopy.DropLastElements(diffQl);
135: 
136:         c0 = a * scopy + ns * e;
137:         c1 = -a;
138:     }
139:     else {
140:         // Use secret key as is
141:         c0 = a * s + ns * e;
142:         c1 = -a;
143:     }
144: 
145:     return std::make_shared<std::vector<DCRTPoly>>(std::initializer_list<DCRTPoly>({std::move(c0), std::move(c1)}));
146: }
