148: std::shared_ptr<std::vector<DCRTPoly>> PKERNS::EncryptZeroCore(const PublicKey<DCRTPoly> publicKey,
149:                                                                const std::shared_ptr<ParmType> params) const {
150:     const auto cryptoParams = std::dynamic_pointer_cast<CryptoParametersRNS>(publicKey->GetCryptoParameters());
151: 
152:     const std::vector<DCRTPoly>& pk = publicKey->GetPublicElements();
153:     const auto ns                   = cryptoParams->GetNoiseScale();
154:     const DggType& dgg              = cryptoParams->GetDiscreteGaussianGenerator();
155: 
156:     TugType tug;
157: 
158:     const std::shared_ptr<ParmType> elementParams = (params == nullptr) ? cryptoParams->GetElementParams() : params;
159:     // TODO (dsuponit): "tug" must be assigned with TernaryUniformGenerator. Otherwise the DCRTPoly constructor crashes.
160:     // check other files if "tug" is properly assigned
161:     // if (cryptoParams->GetSecretKeyDist() != GAUSSIAN) {
162:     //    OPENFHE_THROW("TugType tug must be assigned");
163:     //}
164:     DCRTPoly v = cryptoParams->GetSecretKeyDist() == GAUSSIAN ? DCRTPoly(dgg, elementParams, Format::EVALUATION) :
165:                                                                 DCRTPoly(tug, elementParams, Format::EVALUATION);
166: 
167:     // noise generation with the discrete gaussian generator dgg
168:     DCRTPoly e0(dgg, elementParams, Format::EVALUATION);
169:     DCRTPoly e1(dgg, elementParams, Format::EVALUATION);
170: 
171:     uint32_t sizeQ  = pk[0].GetParams()->GetParams().size();
172:     uint32_t sizeQl = elementParams->GetParams().size();
173: 
174:     DCRTPoly c0, c1;
175:     if (sizeQl != sizeQ) {
176:         // Clone public keys because we need to drop towers.
177:         DCRTPoly p0 = pk[0].Clone();
178:         DCRTPoly p1 = pk[1].Clone();
179: 
180:         uint32_t diffQl = sizeQ - sizeQl;
181:         p0.DropLastElements(diffQl);
182:         p1.DropLastElements(diffQl);
183: 
184:         c0 = p0 * v + ns * e0;
185:         c1 = p1 * v + ns * e1;
186:     }
187:     else {
188:         // Use public keys as they are
189:         const DCRTPoly& p0 = pk[0];
190:         const DCRTPoly& p1 = pk[1];
191: 
192:         c0 = p0 * v + ns * e0;
193:         c1 = p1 * v + ns * e1;
194:     }
195: 
196:     return std::make_shared<std::vector<DCRTPoly>>(std::initializer_list<DCRTPoly>({std::move(c0), std::move(c1)}));

